/* the Wishing Fountain in the town square, in the same style (drawn by the core map's NPC drawing when loaded) */
const FT={svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><defs><linearGradient id="st" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ece6d6"/><stop offset=".55" stop-color="#d6cdb8"/><stop offset="1" stop-color="#b9ae98"/></linearGradient><linearGradient id="wt" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a5d8ff"/><stop offset=".55" stop-color="#74c0fc"/><stop offset="1" stop-color="#4dabf7"/></linearGradient></defs><ellipse cx="60" cy="113" rx="50" ry="9.0" fill="rgba(0,0,0,.22)"/> <path d="M10 92 q0 -14 50 -14 q50 0 50 14 v12 q0 12 -50 12 q-50 0 -50 -12 Z" fill="url(#st)" stroke="#3b2a1e" stroke-width="4" stroke-linejoin="round"/> <ellipse cx="60" cy="92" rx="44" ry="10" fill="url(#wt)" stroke="#3b2a1e" stroke-width="3"/> <ellipse cx="44" cy="93" rx="3.2" ry="1.8" fill="#ffd43b" stroke="#3b2a1e" stroke-width="1"/><ellipse cx="78" cy="95" rx="3.2" ry="1.8" fill="#ffd43b" stroke="#3b2a1e" stroke-width="1"/><ellipse cx="66" cy="90" rx="2.6" ry="1.5" fill="#ffe066" stroke="#3b2a1e" stroke-width="1"/> <path d="M22 100 h76" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".45"/> <rect x="53" y="52" width="14" height="40" rx="3" fill="url(#st)" stroke="#3b2a1e" stroke-width="3.5"/> <path d="M32 58 q0 -9 28 -9 q28 0 28 9 v4 q0 8 -28 8 q-28 0 -28 -8 Z" fill="url(#st)" stroke="#3b2a1e" stroke-width="3.5" stroke-linejoin="round"/> <ellipse cx="60" cy="58" rx="24" ry="5.5" fill="url(#wt)" stroke="#3b2a1e" stroke-width="2.5"/> <rect x="56" y="30" width="8" height="26" rx="3" fill="url(#st)" stroke="#3b2a1e" stroke-width="3"/> </svg>`};let fim=null;FT.img=()=>{if(!fim){fim=new Image();fim.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(FT.svg);}return fim;};/* the water moves (owner, Oct 2026): jets that rise and fall, droplets running down from the top bowl, ripples spreading in the pool.
   Drawn over the picture in the fountain's own 120×120 space; (x0,y0) is the picture's top-left, s its size. */
FT.anim=(ctx,x0,y0,s,now)=>{const k=s/120,X=u=>x0+u*k,Y=v=>y0+v*k,q=(a,c,b,t)=>(1-t)*(1-t)*a+2*(1-t)*t*c+t*t*b;ctx.save();ctx.lineCap='round';
 const h=15+3*Math.sin(now/170),pk=17+2.5*Math.sin(now/210);
 for(const [w,c] of [[4.8,'#74c0fc'],[1.7,'#e7f5ff']]){ctx.strokeStyle=c;ctx.lineWidth=w*k;ctx.beginPath();ctx.moveTo(X(60),Y(30));ctx.lineTo(X(60),Y(30-h));
  ctx.moveTo(X(60),Y(30));ctx.quadraticCurveTo(X(46),Y(pk),X(34),Y(36));ctx.moveTo(X(60),Y(30));ctx.quadraticCurveTo(X(74),Y(pk),X(86),Y(36));ctx.stroke();}
 ctx.fillStyle='#e7f5ff';ctx.strokeStyle='#4dabf7';ctx.lineWidth=1.2*k;ctx.beginPath();ctx.arc(X(60),Y(30-h),2.6*k,0,7);ctx.fill();ctx.stroke();
 ctx.strokeStyle='rgba(116,192,252,.85)';ctx.lineWidth=3*k;ctx.beginPath();ctx.moveTo(X(34),Y(61));ctx.quadraticCurveTo(X(24),Y(66),X(18),Y(88));ctx.moveTo(X(86),Y(61));ctx.quadraticCurveTo(X(96),Y(66),X(102),Y(88));ctx.stroke();
 ctx.fillStyle='#e7f5ff';for(let i=0;i<3;i++)for(const sd of [-1,1]){const t=((now/650)+i/3)%1,u=60+sd*q(26,36,42,t),v=q(61,66,88,t);ctx.beginPath();ctx.arc(X(u),Y(v),1.9*k,0,7);ctx.fill();}
 ctx.save();ctx.beginPath();ctx.ellipse(X(60),Y(92),44*k,10*k,0,0,7);ctx.clip();for(let j=0;j<2;j++){const ph=((now/1700)+j/2)%1;ctx.strokeStyle=`rgba(255,255,255,${(1-ph)*.75})`;ctx.lineWidth=1.6*k;ctx.beginPath();ctx.ellipse(X(60),Y(93),(12+30*ph)*k,(2.6+6*ph)*k,0,0,7);ctx.stroke();}ctx.restore();
 ctx.save();ctx.beginPath();ctx.ellipse(X(60),Y(58),24*k,5.5*k,0,0,7);ctx.clip();const p2=(now/1200)%1;ctx.strokeStyle=`rgba(255,255,255,${(1-p2)*.7})`;ctx.lineWidth=1.3*k;ctx.beginPath();ctx.ellipse(X(60),Y(58.5),(6+16*p2)*k,(1.4+3.6*p2)*k,0,0,7);ctx.stroke();ctx.restore();
 ctx.restore();};
window.MQ_FOUNTAIN_ART=FT;
